window.ScripturaLexicons.BDAG_PART_0027 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ana-bdag\" data-source=\"BDAG\" data-search=\"ἀνά ana preposição preposicao acusativo acima até ate entre meio por vez cada cada um distributivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνά</td><td>Preposição + acusativo</td><td>em meio a; por sua vez; cada</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabathmos-bdag\" data-source=\"BDAG\" data-search=\"ἀναβαθμός anabathmos degrau degraus escada escadaria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβαθμός</td><td>Substantivo masculino</td><td>degrau; escadaria</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabaino-bdag\" data-source=\"BDAG\" data-search=\"ἀναβαίνω anabaino subir ascender ir para cima embarcar crescer surgir vir à mente vir a mente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβαίνω</td><td>Verbo</td><td>subir; ascender; ir para cima</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaballo-bdag\" data-source=\"BDAG\" data-search=\"ἀναβάλλω anaballo adiar protelar remeter julgamento julgamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβάλλω</td><td>Verbo</td><td>adiar; remeter</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabates-bdag\" data-source=\"BDAG\" data-search=\"ἀναβάτης anabates condutor cocheiro cavaleiro cavaleiro ambiguidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβάτης</td><td>Substantivo masculino</td><td>condutor; cavaleiro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabibazo-bdag\" data-source=\"BDAG\" data-search=\"ἀναβιβάζω anabibazo puxar para cima trazer para cima rede margem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβιβάζω</td><td>Verbo</td><td>puxar para cima</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabioo-bdag\" data-source=\"BDAG\" data-search=\"ἀναβιόω anabioo reviver voltar à vida voltar a vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβιόω</td><td>Verbo</td><td>voltar à vida; reviver</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anablepo-bdag\" data-source=\"BDAG\" data-search=\"ἀναβλέπω anablepo olhar para cima recobrar vista enxergar receber visão visao BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβλέπω</td><td>Verbo</td><td>olhar para cima; recobrar a vista</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anablepsis-bdag\" data-source=\"BDAG\" data-search=\"ἀνάβλεψις anablepsis recuperação restauração vista visão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάβλεψις</td><td>Substantivo feminino</td><td>recuperação da vista</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaboao-bdag\" data-source=\"BDAG\" data-search=\"ἀναβοάω anaboao gritar clamar exclamar voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβοάω</td><td>Verbo</td><td>gritar; clamar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anabole-bdag\" data-source=\"BDAG\" data-search=\"ἀναβολή anabole adiamento protelação processo legal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναβολή</td><td>Substantivo feminino</td><td>adiamento; protelação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagaion-bdag\" data-source=\"BDAG\" data-search=\"ἀνάγαιον anagaion aposento superior sala andar de cima BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάγαιον</td><td>Substantivo neutro</td><td>aposento no andar de cima</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anangello-bdag\" data-source=\"BDAG\" data-search=\"ἀναγγέλλω anangello relatar anunciar proclamar ensinar informar divulgar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγγέλλω</td><td>Verbo</td><td>relatar; anunciar; proclamar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagennao-bdag\" data-source=\"BDAG\" data-search=\"ἀναγεννάω anagennao gerar de novo fazer nascer de novo renascimento espiritual regeneração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγεννάω</td><td>Verbo</td><td>gerar de novo; fazer nascer de novo</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-ana-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνά</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aná⟧</span><span class=\"separator\">·</span><span>preposição com acusativo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Desde Homero.) Literalmente, <strong>para cima, até em cima</strong>; rara no grego posterior.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <span class=\"greek\">ἀνὰ μέσον</span>, <strong>em uma posição no meio</strong> — Aristóteles e outros; Políbio; Diodoro Sículo; inscrições; papiros; LXX; Enoque; TestAbr B 8, p. 112, 21 e outros; JosAs 4.5s.; ApcMos; EpArist — veja E. Lohmeyer, <em>Diatheke</em> (1913), 86 n. 1; Nägeli 30; Rossberg 34; M. Johannessohn, <em>Präp.</em> 170–73, especialmente 170, 6 —; Justino, <em>D.</em> 107, 4, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JON.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jn 4.11</a>. Com genitivo:</p>\n<p class=\"entry-text\"><strong>a. De posição em uma área: entre, no meio de.</strong> Compare PGM 36, 302. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὰ μέσον τοῦ σίτου\" data-meanings=\"no meio do trigo\">ἀνὰ μέσον τοῦ σίτου</span>, <strong>no meio do trigo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.25</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὰ μέσον τῶν ὁρίων Δεκαπόλεως\" data-meanings=\"para dentro da região da Decápole; pelo meio da região da Decápole\">ἀνὰ μέσον τῶν ὁρίων Δεκαπόλεως</span>, <strong>para dentro da região da Decápole</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.31</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤλθωσιν ἀνὰ μέσον τῆς ὁδοῦ\" data-meanings=\"tinham percorrido metade do caminho\">ἤλθωσιν ἀνὰ μέσον τῆς ὁδοῦ</span>, <strong>tinham percorrido metade do caminho</strong>, GJs 17.3.</p>\n<p class=\"entry-text\"><strong>b. De pessoas: entre, no meio de.</strong> Diodoro Sículo 11.90, 3, <span class=\"greek\">ἀνὰ μέσον ποταμῶν δυοῖν</span>; 12.9, 2; 14.80, 2; 17.52, 1; Estrabão 4.4, 2; En 13.9. <span class=\"greek\">διαστεῖλαι ἀνὰ μέσον δικαίου καὶ ἁμαρτωλοῦ</span>, PsSol 2.34; compare <span class=\"greek\">ἀνὰ μέσον τῶν δύο πυλῶν</span>, TestAbr B 8, p. 112, 21 [Stone p. 72]; GPt 4.10 = ASyn. 344, 73; Hs 9, 2, 3; 9, 15, 2.</p>\n<p class=\"entry-text\">Em expressão abreviada — <strong>se o texto não estiver danificado, o que Mlt. 99 põe em dúvida</strong> —, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διακρῖναι ἀνὰ μέσον τοῦ ἀδελφοῦ αὐτοῦ\" data-meanings=\"decidir um caso entre membros\">διακρῖναι ἀνὰ μέσον τοῦ ἀδελφοῦ αὐτοῦ</span>, <strong>decidir um caso entre membros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6.5</a>. Sobre o encurtamento, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 25.18</a> v.l., <span class=\"greek\">ἀνὰ μέσον τοῦ πλησίον αὐτοῦ ἀναπεσεῖται ὁ ἀνήρ</span>; veja também <span class=\"greek\">μέσος</span> 1b, início. Compare ainda ações judiciais <span class=\"greek\">ἀνὰ μέσον Ἑλλήνων</span>, SEG IX, 8, 64; JosAs 28.6, <span class=\"greek\">κρινεῖ κύριος ἀνὰ μέσον ἐμοῦ καὶ ὑμῶν</span>.</p>\n<p class=\"entry-text\">Com o sentido <strong>no meio de</strong>, considerado não ático — I. Bekker, <em>Anecd.</em> I (1814), 80, 24: <span class=\"greek\">ἀνὰ μέσον· ἀντὶ τοῦ ἐν μέσῳ</span> —, compare Diodoro Sículo 1.30, 4, <span class=\"greek\">ἀνὰ μέσον τῆς Κοίλης Συρίας</span>; PPetr III, 37a II, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 26.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 16.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">19.1</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀρνίον τὸ ἀνὰ μέσον τοῦ θρόνου\" data-meanings=\"o Cordeiro no centro do trono\">τὸ ἀρνίον τὸ ἀνὰ μέσον τοῦ θρόνου</span>, <strong>o Cordeiro no centro do trono</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7.17</a>. <span class=\"greek\">ἀνὰ μέσον ἐκκλησίας</span>, <strong>no meio da congregação</strong>, B 6.16.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <span class=\"greek\">ἀνὰ μέρος</span>, literalmente <strong>até uma parte</strong> ou <strong>segundo uma parte</strong>: <strong>seguindo em sequência, por sua vez</strong> — Aristóteles, <em>Pol.</em> 1287a, 17; Políbio 4.20, 10, <span class=\"greek\">ἀνὰ μέρος ᾂδειν</span>; Apiano, <em>Iber.</em> 82 §357; <em>Mithrid.</em> 22 §83; <em>Bell. Civ.</em> 3.44 §183; SEG IX, 8, 122 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.27</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Distributivamente, com números: cada, cada um, por pessoa, de cada vez.</strong> Aristófanes, <em>Ran.</em> 554s.; Xenofonte, <em>An.</em> 4.6, 4; SEG IX, 8, 27; PAmh II, 88 [128 d.C.]; POxy 819 [séc. I d.C.] e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">3Rs 18.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1CH.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Cr 15.26</a>; En 10.19; TestJob 44.5; JosAs; Josefo, <em>Ant.</em> 8.179; 17.172; Rdm. 20.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὰ δηνάριον\" data-meanings=\"um denário para cada um\">ἀνὰ δηνάριον</span>, <strong>um denário para cada um</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.9s.</a>. <span class=\"greek\">ἀνὰ λαμπάδα</span>, <strong>uma lâmpada para cada uma</strong>, GJs 7.2. <span class=\"greek\">ἀνὰ ῥάβδον</span>, <strong>um bastão para cada um</strong>, GJs 8.3 — não em papiros. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέστειλεν αὐτοὺς ἀνὰ δύο\" data-meanings=\"enviou-os dois a dois\">ἀπέστειλεν αὐτοὺς ἀνὰ δύο</span>, <strong>enviou-os dois a dois</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.1</a>. <span class=\"greek\">κλισίας ὡσεὶ ἀνὰ πεντήκοντα</span>, <strong>grupos de cerca de cinquenta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.14</a>. <span class=\"greek\">ἀνὰ μετρητὰς δύο ἢ τρεῖς</span>, <strong>duas ou três medidas cada</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.6</a>; compare Diodoro Sículo 3.13, 2, <span class=\"greek\">ἀνὰ τρεῖς ἢ δύο</span>. <span class=\"greek\">ἀνὰ ἑκατὸν καὶ ἀνὰ πεντήκοντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.40</a>; v.l. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4.8</a>; GPt 9.35 = ASyn. 353, 81.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὰ μέσον αὐτῶν ἀνὰ δύο παρθένοι\" data-meanings=\"entre elas — as virgens nos quatro cantos — duas virgens para cada lado\">ἀνὰ μέσον αὐτῶν ἀνὰ δύο παρθένοι</span>, <strong>entre elas — as virgens nos quatro cantos — duas virgens para cada lado</strong>, Hs 9, 2, 3; veja M. Dibelius, <em>Hdb.</em> ad loc. Em <span class=\"greek\">ἀνὰ δύο παρθένοι</span>, <span class=\"greek\">ἀνά</span> tornou-se fixo como advérbio. Do mesmo modo, <span class=\"greek\">ἀνὰ εἷς ἕκαστος τῶν πυλώνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21.21</a>; B-D-F §§204, 305; Rob. 571. Sobre <span class=\"greek\">ἀνὰ δύο δύο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.1</a>, compare AcPh 142 [Aa II/2, 79, 6] e <span class=\"greek\">δύο</span> b.</p>\n<p class=\"entry-text\"><strong>Bibliografia especial sobre preposições:</strong> B-D-F §§203–40; Rdm.², pp. 137–46; Mlt-H. 292–332; Rob. 553–649; Mayser II/2, pp. 152–68; 337–543. M. Johannessohn, <em>D. Gebrauch d. Präpositionen in LXX</em>, <em>NGG</em>, Beiheft (1926). P. Regard, <em>Contribution à l’Étude des Prépositions dans la langue du NT</em> (1919). F. Krebs, <em>D. Präpositionen b. Polybius</em>, diss. Würzburg (1882); F. Krumbholz, <em>De praepos. usu Appianeo</em>, diss. Jena (1885); P. Melcher, <em>De sermone Epict.</em>, <em>Diss. philol. Halenses</em> 17, 1 (1905); J. Käser, <em>D. Präpos. b. Dionys. Hal.</em>, diss. Erlangen (1915); H. Teykowski, <em>D. Präpositions-gebr. b. Menander</em>, diss. Bonn (1940). R. Günther, <em>D. Präpos. in d. griech. Dialektinschriften</em>, <em>IndogF</em> 20 (1906), 1–163; E. Nachmanson, <em>Eranos</em> 9 (1909), 66ss.; os trabalhos de Kuhring e Rossberg sobre o uso nos papiros; G. Rudberg, <em>Ad usum circumscribentem praepositionum graec.</em>, <em>Eranos</em> 19 (1922), 173–206. — DELG. M-M.</p>\n</section></article><article id=\"entry-anabathmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβαθμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anabathmós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Heródoto e outros; Eliano, <em>NA</em> 6.61; 11.31; Cássio Dio 65.21; 68.5; Fílon, <em>Leg. ad Gai.</em> 77; PSI 546, 3; LXX; DELG s.v. <span class=\"greek\">βαίνω</span>, p. 157.) <strong>Degrau</strong>; no plural, <strong>lanço de escadas, escadaria</strong>.</p>\n<p class=\"entry-text\">Dos degraus que levavam do pátio do templo à fortaleza Antônia: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτε ἐγένετο ἐπὶ τοὺς ἀναβαθμούς\" data-meanings=\"quando chegou aos degraus\">ὅτε ἐγένετο ἐπὶ τοὺς ἀναβαθμούς</span>, <strong>quando chegou aos degraus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.35</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑστὼς ἐπὶ τῶν ἀναβαθμῶν\" data-meanings=\"de pé sobre os degraus\">ἑστὼς ἐπὶ τῶν ἀναβαθμῶν</span>, <strong>de pé sobre os degraus</strong>, v. 40; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Cr 9.19</a>. Schürer I 366. — M-M. TW.</p>\n</section></article><article id=\"entry-anabaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anabaínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναβήσομαι</span>; 2º aoristo <span class=\"greek\">ἀνέβην</span>; imperativo <span class=\"greek\">ἀνάβα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4.1</a>; plural <span class=\"greek\">ἀνάβατε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">11.12</a> — v.l. <span class=\"greek\">ἀνάβητε</span>; veja W-S. §13, 22; Mlt-H. 209s. —; perfeito <span class=\"greek\">ἀναβέβηκα</span>. Desde Homero.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Estar em movimento para cima, subir, ascender.</strong></p>\n<p class=\"entry-text\"><strong>a. De seres vivos.</strong> <strong>α. De movimento numa direção, sem ênfase especial no ato de ascender.</strong> <span class=\"greek\">εἰς τὸ ὑπερῷον</span>, <strong>para o aposento superior</strong> — compare Josefo, <em>Vita</em> 146 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.13</a>. <span class=\"greek\">εἰς τὸ ὄρος</span>, <strong>para o monte</strong> — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 19.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a> e outros; Josefo, <em>C. Ap.</em> 2.25; Irineu 1.14.6 [Harv. I 139, 8] —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">14.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">15.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.28</a>.</p>\n<p class=\"entry-text\">Especialmente da estrada para Jerusalém, situada em terreno elevado — como o hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">עָלָה</bdi>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2ES.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Ed 1.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Ed 2.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 13.2</a>; Josefo, <em>Bell.</em> 2.40; <em>Ant.</em> 14.270 —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.17s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.32s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">19.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.55\" target=\"_blank\" rel=\"noopener noreferrer\">11.55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">21.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">24.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">25.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.1</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">εἰς τὸ ἱερόν</span>, <strong>subir ao templo</strong>, porque o templo ficava numa elevação — UPZ 41, 5; 42, 4 [162 a.C.], <span class=\"greek\">ἀ. εἰς τὸ ἱερὸν θυσιάσαι</span>; 70, 19s. [152/151 a.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.37.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 37.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.37.14\" target=\"_blank\" rel=\"noopener noreferrer\">14</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.38.22\" target=\"_blank\" rel=\"noopener noreferrer\">38.22</a>; Josefo, <em>Ant.</em> 12.164s., <span class=\"greek\">ἀναβὰς εἰς τὸ ἱερὸν … καταβὰς ἐκ τ. ἱεροῦ</span> —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.1</a>. <span class=\"greek\">ἐν ναῷ</span>, GJs 7.2; <span class=\"greek\">ἐν τῇ ὀρινῇ</span>, 22.3.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβαίνειν εἰς τὴν ἑορτήν\" data-meanings=\"subir para a festa\">ἀ. εἰς τὴν ἑορτήν</span>, <strong>subir para a festa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.8</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">10</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">12.20</a> — compare BGU 48, 19 [séc. III d.C.], <span class=\"greek\">ἐὰν ἀναβῇς τῇ ἑορτῇ</span>; Sb 7994, 21. Com <span class=\"greek\">ἐπί</span> + acusativo — Xenofonte, <em>Cyr.</em> 6.4.9; PsSol 2.2; Josefo, <em>Bell.</em> 6.285; Justino, <em>A II</em> 12.7 —: <span class=\"greek\">ἐπὶ τὸ δῶμα</span>, <strong>subir ao terraço</strong> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.9.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 9.51</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.9</a>. Com <span class=\"greek\">πρός</span> + acusativo — UPZ 62, 31 [161 a.C.] —: <span class=\"greek\">πρὸς τοὺς ἀποστόλους καὶ πρεσβυτέρους εἰς Ἰερουσαλὴμ περὶ τοῦ ζητήματος τούτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.2</a>.</p>\n<p class=\"entry-text\">Com indicação do lugar de onde alguém sobe: <span class=\"greek\">ἀπό</span> + genitivo — Xenofonte, <em>Hell.</em> 6.5.26; Políbio 10.4.6; Dio Crisóstomo 79 [28], 1 —: <span class=\"greek\">ἀπὸ τοῦ ὕδατος</span>, <strong>subir da água</strong>, no batismo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.16</a>; Justino, <em>D.</em> 103.6, <span class=\"greek\">ἀπὸ τοῦ ποταμοῦ</span>. Para isso, <span class=\"greek\">ἐκ</span> + genitivo — Xenofonte, <em>Hell.</em> 5.4.58 —: <span class=\"greek\">ἐκ τοῦ ὕδατος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.39</a>. <span class=\"greek\">δι’ ὕδατος</span>, Hs 9, 16, 2. Da viagem para a Judeia: <span class=\"greek\">ἀπὸ τῆς Γαλιλαίας εἰς τὴν Ἰουδαίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.4</a>. De modo geral, <span class=\"greek\">ἀλλαχόθεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.1</a>.</p>\n<p class=\"entry-text\">De navios: <strong>embarcar, entrar</strong> — Apiano, <em>Bell. Civ.</em> 2.85 §358 v.l., <span class=\"greek\">ἀ. ἐς τὸ σκάφος</span> —; <span class=\"greek\">εἰς τὸ πλοῖον</span> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JON.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jn 1.3</a> v.l. —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.22</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.24</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.6</a> — também <span class=\"greek\">ἐνέβησαν, ἐπέβησαν</span> —; AcPl Ha 5, 15. Absolutamente, <span class=\"greek\">ἀναβάς</span>, <strong>subiu novamente ao terceiro andar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.11</a>; <strong>subiu a Jerusalém</strong> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.48.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 48.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">1Ed 1.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 3.15</a>; compare o uso de <span class=\"greek\">ἀναβαίνω</span> para uma viagem à capital em Epicteto 3.7.13; POxy 935, 13; 1157, linhas 7, 25s.; BGU 1097, 3 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.22</a>.</p>\n<p class=\"entry-text\"><strong>β. De qualquer movimento para cima: subir, ascender.</strong> <span class=\"greek\">εἰς (τοὺς) οὐρανούς</span> ou <span class=\"greek\">εἰς τὸν οὐρανόν</span> — Caritão 3.2.5, a Zeus; Polieno 7.22, a Hera; Artemidoro 4.72, onde <span class=\"greek\">τὸ ἀ. εἰς οὐρανόν</span> significa <span class=\"greek\">ὑπερβάλλουσα εὐδαιμονία</span>; En 14.5; Justino, <em>D.</em> 36.5; 85.2 e outros; Diógenes, <em>Ep.</em> 33.4, p. 142, 5 Malherbe, <span class=\"greek\">ἀ. ἐπὶ τὸν οὐ.</span>; Herm. Wr. 10.25; 11.21a; PGM 4, 546; SibOr 5, 72; compare AscIs 2.16 = PAmh 1 —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.6</a> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.30.12\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 30.12</a> —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11.12</a>; B 15.9. Para isso, <span class=\"greek\">εἰς ὕψος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.8s.</a> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.67.19\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 67.19</a>; Justino, <em>D.</em> 39.5 —; <span class=\"greek\">ὑπεράνω πάντων τῶν οὐρανῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">v. 10</a>.</p>\n<p class=\"entry-text\">Parafraseado por <span class=\"greek\">ἀ. ὅπου ἦν τὸ πρότερον</span>, <strong>subir para onde estava antes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.62\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.62</a>; <span class=\"greek\">ὧδε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">11.12</a>; <span class=\"greek\">ἐπὶ τὸ πλάτος τῆς γῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">20.9</a>. Com indicação do lugar de onde se sobe: <span class=\"greek\">ἐκ τῆς ἀβύσσου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">11.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">17.8</a>; <span class=\"greek\">ἐκ τῆς θαλάσσης</span> — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 7.3</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13.1</a>; <span class=\"greek\">ἐκ τῆς γῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">v. 11</a>.</p>\n<p class=\"entry-text\">Absolutamente, de anjos — Orígenes, <em>C. Cels.</em> 5.4.9; compare Irineu 1.9.3 [Harv. I 84, 6], do Logos —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγγέλους τοῦ θεοῦ ἀναβαίνοντας καὶ καταβαίνοντας\" data-meanings=\"anjos de Deus subindo e descendo\">ἀγγέλους τοῦ θεοῦ ἀναβαίνοντας καὶ καταβαίνοντας</span>, <strong>anjos de Deus subindo e descendo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.51</a> — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.28.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 28.12</a>; veja <span class=\"greek\">ἄγγελος</span> 2; também W. Thüsing s.v. <span class=\"greek\">δόξα</span>, ao fim; J. Davies, <em>He Ascended into Heaven</em> (1958). <strong>Trepar, subir</strong> <span class=\"greek\">ἐπὶ συκομορέαν</span>, <strong>a um sicômoro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.4</a> — Diodoro Sículo 3.24.2, <span class=\"greek\">ἐπὶ τὰ δένδρα</span>; Esopo, <em>Fab.</em> 32 P. = 48 H.; SIG 1168, 91, <span class=\"greek\">ἐπὶ δένδρον ἀ.</span>.</p>\n<p class=\"entry-text\">Representando um passivo — Wlh., <em>Einl.</em>² 19; compare Sinésio, <em>Ep.</em> 67, p. 215d, onde uma carga “é colocada” <span class=\"greek\">ἐπί τι</span> —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἀναβάντα πρῶτον ἰχθύν\" data-meanings=\"o primeiro peixe que apanhares\">τὸν ἀναβάντα πρῶτον ἰχθύν</span>, <strong>o primeiro peixe que apanhares</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.27</a>; B-D-F §315.</p>\n<p class=\"entry-text\"><strong>b. De coisas.</strong> Da fumaça — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 19.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 8.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.34.10\" target=\"_blank\" rel=\"noopener noreferrer\">Is 34.10</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">9.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">19.3</a>. Rochas <span class=\"greek\">ἐκ τοῦ πεδίου</span>, Hs 9, 2, 1; pedras <span class=\"greek\">ἐκ βυθοῦ</span>, 9, 3, 3; de videiras que se agarram aos olmos, <strong>subir</strong>, Hs 2.3. De plantas, também <strong>brotar, crescer</strong> — Teofrasto, <em>HP</em> 8.3.2 —: espinheiros — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Is 5.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.32.13\" target=\"_blank\" rel=\"noopener noreferrer\">32.13</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.7</a>. <span class=\"greek\">ὅταν σπαρῇ ἀναβαίνει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">v. 32</a>; com <span class=\"greek\">αὐξάνεσθαι</span>, v. 8. Árvores crescem, B 11.10.</p>\n<p class=\"entry-text\">Orações <strong>sobem ao céu</strong> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 5.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">3Mc 5.9</a>; En 9.10, <span class=\"greek\">στεναγμός</span>; <em>Proverbia Aesopi</em> 79 P., <span class=\"greek\">ἀγαθῷ θεῷ λίβανος οὐκ ἀναβαίνει</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.4</a>. Figuradamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνέβη φάσις τῷ χιλιάρχῳ\" data-meanings=\"uma notícia chegou ao tribuno\">ἀνέβη φάσις τῷ χιλιάρχῳ</span>, <strong>uma notícia chegou ao tribuno</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.31</a>. <span class=\"greek\">ἀνέβη ὁ κλῆρος ἐπὶ Συμεών</span>, isto é, <strong>o sacerdócio passou a Simeão</strong>, GJs 24.4 — semelhante do reino, Heródoto 1.109, <span class=\"greek\">ἐς τὴν θυγατέρα</span>; 7.205, <span class=\"greek\">ἐς Λεωνίδην</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Semitismo:</strong> <span class=\"greek\">ἀναβαίνω ἐπὶ καρδίαν</span>, literalmente <strong>subir ao coração</strong>, isto é, <strong>vir à mente</strong>, alguém começar a pensar em alguma coisa — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2KI.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">4Rs 12.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 3.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.51.21\" target=\"_blank\" rel=\"noopener noreferrer\">51.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.65.16\" target=\"_blank\" rel=\"noopener noreferrer\">Is 65.16</a>; M. Wilcox, <em>The Semitisms of Acts</em> (1965), 63 —. <span class=\"greek\">οὐκ ἀ. ἐπὶ καρδίαν</span>, <strong>nunca nos veio à mente</strong>, pois o coração era considerado o órgão do pensamento — = hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">עָלָה עַל לֵב</bdi>. O grego dizia <span class=\"greek\">ἐπὶ νοῦν ἀναβαίνει</span> — Sinésio, <em>Ep.</em> 44, p. 182c — ou <span class=\"greek\">ἦλθεν</span> — Marino, <em>Vi. Procli</em> 17 Boiss. —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2.9</a>; M. Philonenko, <em>TZ</em> 15 (1959), 51s.; Hv 1, 1, 8; 3, 7, 2 e outros — veja <span class=\"greek\">καρδία</span> 1bβ. Também <span class=\"greek\">ἀ. ἐν τῇ καρδίᾳ</span>, Hs 5, 1, 5. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διαλογισμοὶ ἀναβαίνουσιν ἐν τῇ καρδίᾳ\" data-meanings=\"dúvidas surgem em vossos corações\">διαλογισμοὶ ἀναβαίνουσιν ἐν τῇ καρδίᾳ</span>, <strong>dúvidas surgem em vossos corações</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.38</a>. — M-M.</p>\n</section></article><article id=\"entry-anaballo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anabállō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Veja <span class=\"greek\">βάλλω</span>; Homero e posteriores em vários sentidos; LXX; Atenágoras 13.2, por <span class=\"greek\">ἐξήνεγκεν</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 1.12</a>.) 2º aoristo ativo <span class=\"greek\">ἀνέβαλον</span>, LXX; médio <span class=\"greek\">ἀνεβαλόμην</span>, LXX; particípio perfeito <span class=\"greek\">ἀναβεβλημένος</span>, “vestindo” um manto. No ativo e no médio, <strong>adiar, protelar</strong> — médio: Hesíodo, <em>Works</em> 410, não se deve <span class=\"greek\">ἀναβάλλεσθαι</span> nada <span class=\"greek\">ἐς αὔριον</span>; Nicolau de Damasco 90 Fgm. 130, 43 Jac.; Diodoro Sículo 14.100.1, <span class=\"greek\">εἰς ἕτερον καιρὸν ἀνεβάλετο</span>; Syntipas p. 52, 2; Josefo, <em>Ant.</em> 4.288; 14.28; PCairZen 412, 13.</p>\n<p class=\"entry-text\">No único exemplo da literatura abrangida pelo BDAG, ocorre no médio e como termo técnico jurídico: <strong>adiar um julgamento, remeter alguém</strong> — Heródoto, Demóstenes e outros; PTebt 22, 9 [112 a.C.], “remeter questões”; Josefo, <em>Ant.</em> 14.177 —, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνεβάλετο αὐτοὺς ὁ Φῆλιξ\" data-meanings=\"Félix adiou o caso deles; Félix os remeteu\">ἀνεβάλετο αὐτοὺς ὁ Φῆλιξ</span>, <strong>Félix adiou o caso deles</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.22</a>; compare o latim <em>ampliare aliquem</em>, Cícero, <em>Verr.</em> 1.29. — M-M.</p>\n</section></article><article id=\"entry-anabates-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβάτης</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anabátēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Platão, Xenofonte e outros; LXX; PsSol 17.33; DELG s.v. <span class=\"greek\">βαίνω</span>, p. 157.) Em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅρματα καὶ ἀναβάται αὐτῶν\" data-meanings=\"carros e seus condutores; ou carros e os cavaleiros deles\">ἅρματα καὶ ἀναβάται αὐτῶν</span>, permanece <strong>em aberto</strong> a que se refere <span class=\"greek\">αὐτῶν</span>. Se se refere a <span class=\"greek\">ἅρματα</span>, <span class=\"greek\">ἀναβάται</span> significa <strong>condutores dos carros</strong>; se se refere aos egípcios, conserva o sentido usual <strong>cavaleiros</strong>, sentido presente nas passagens do AT que servem de base a 1 Cl 51.5 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 14.23</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">26</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>. O BDAG não escolhe entre as duas análises.</p>\n</section></article><article id=\"entry-anabibazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβιβάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anabibázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναβιβάσω</span>, LXX; <span class=\"greek\">ἀναβιβῶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/AMO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Am 8.10</a>; <span class=\"greek\">ἀναβάσω</span>, ApcSed 2.2; 1º aoristo <span class=\"greek\">ἀνεβίβασα</span>, LXX. Heródoto e outros; TestSol 25.7 [PQ]; rec. C 10.2; TestJob 52.10; PCairZen 736, 36 [séc. III a.C.]; POxy 513, 27; Fílon, <em>De Jos.</em> 120; Josefo, <em>Ant.</em> 20.60; Taciano 10.2; DELG s.v. <span class=\"greek\">βαίνω</span>, p. 156, 3.</p>\n<p class=\"entry-text\"><strong>Trazer ou puxar para cima</strong>, de uma rede: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβιβάσαντες ἐπὶ τὸν αἰγιαλόν\" data-meanings=\"tendo-a puxado para cima, para a praia\">ἀναβιβάσαντες ἐπὶ τὸν αἰγιαλόν</span>, <strong>puxaram-na para cima, para a praia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.48</a>. Compare Máximo de Tiro 29, 6a, <span class=\"greek\">ἀναβ. ἐπὶ ἵππους ἱππέας</span>, “fazer cavaleiros montarem em cavalos”; Xenofonte, <em>Hell.</em> 1.1.2, <span class=\"greek\">πρὸς τ. γῆν ἀνεβίβαζε τὰς τριήρεις</span>. — M-M.</p>\n</section></article><article id=\"entry-anabioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβιόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anabióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Aristófanes, Andócides, Platão e outros; também Artápano: 726 Fgm. 3, 25 Jac., em Eusébio, <em>PE</em> 9.27.25.) <strong>Voltar à vida, reviver</strong> — Artemidoro 2.62; 4.82; Paléfato p. 60, 6; Filóstrato, <em>Vi. Apoll.</em> 1.1.1; 8.7 p. 324, 27; <em>Heroicus</em> 1.4; Josefo, <em>Ant.</em> 18.14 —, 2 Cl 19.4. — DELG s.v. <span class=\"greek\">βίος</span>.</p>\n</section></article><article id=\"entry-anablepo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβλέπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anablépō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sg. <span class=\"greek\">ἀναβλέψει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 11.8</a> S; 3ª pl. <span class=\"greek\">ἀναβλέψονται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Is 8.21</a>; aoristo <span class=\"greek\">ἀνέβλεψα</span>; imperativo <span class=\"greek\">ἀνάβλεψον</span>. Pré-socráticos, Heródoto, Eurípides e posteriores; papiros; LXX; TestAbr B 12, p. 116, 19 [Stone p. 80] e outros; TestJob 40.3; TestJos 6.2; JosAs; ParJer; ApcMos; ApcrEzk P 2 recto, 9; Josefo, <em>Ant.</em> 10.270; Justino, <em>A I</em> 48.2, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.61.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 61.1</a> e talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.5</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Dirigir a visão para cima, olhar para cima.</strong> Literalmente, <span class=\"greek\">ἀ. εἰς τὸν οὐρανόν</span>, <strong>olhar para o céu</strong> — Xenofonte, <em>Cyr.</em> 6.4.9; Ps.-Platão, <em>Axioch.</em> 370b; Caritão 8.7.2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 4.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.35.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 35.5</a>; Josefo, <em>Ant.</em> 11.64 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">7.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.16</a>; 1 Cl 10.6 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 15.5</a> —; MPol 9.2; 14.1; <span class=\"greek\">εἰς τὸν πόλον</span>, GJs 18.2 — não em papiros.</p>\n<p class=\"entry-text\"><strong>Olhar para cima</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.24</a>. <span class=\"greek\">ἀ. τοῖς ὀφθαλμοῖς</span>, 1 Cl 10.4 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 13.14</a>; compare Xenofonte, <em>Hell.</em> 7.1.30, <span class=\"greek\">ἀν. ὀρθοῖς ὄμμασιν</span> —; MPol 2.3 v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβλέψασαι θεωροῦσιν\" data-meanings=\"quando olharam para cima, viram\">ἀναβλέψασαι θεωροῦσιν</span>, <strong>quando olharam para cima, viram</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">21.1</a>. <span class=\"greek\">ἀνάβλεψον</span>, <strong>olha para cima</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.13a</a>. Com <span class=\"greek\">εἰς αὐτόν</span>, indicando a direção do olhar — Josefo, <em>Ant.</em> 12.24 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.13b</a>; <strong>mas talvez este versículo pertença ao sentido 2a</strong>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Obter visão, pela primeira vez ou novamente; recobrar a vista, passar a enxergar.</strong> <strong>a. Literalmente.</strong> <strong>α.</strong> De cegos que antes enxergavam: <strong>recobrar a vista</strong> — Heródoto 2.111; Aristófanes, <em>Plut.</em> 126; Platão, <em>Phdr.</em> 234b; Ps.-Apolodoro 1.4.3.3; SIG 1173, 4 e 17 [138 d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 14.2</a>; Fílon, <em>Cher.</em> 62 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">17s.</a> A força plena de <span class=\"greek\">ἀνά</span> não é tão clara, mas é bastante provável em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐθέως ἀνέβλεψαν\" data-meanings=\"recobraram imediatamente a vista\">εὐθέως ἀνέβλεψαν</span>, <strong>recobraram imediatamente a vista</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.34</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.52</a>. <span class=\"greek\">(θέλω), ἵνα ἀναβλέψω</span>, <strong>quero recobrar a vista</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.41ss.</a> Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.13b</a>, veja 1.</p>\n<p class=\"entry-text\"><strong>β.</strong> Com perda total da força de <span class=\"greek\">ἀνά</span> “novamente” — veja <span class=\"greek\">ἀναζάω</span> 2; Aristófanes, <em>Plut.</em> 95; 117, <span class=\"greek\">πάλιν ἀν.</span>; Filóstrato, <em>Vi. Soph.</em> 2.1.2 —, de alguém cego de nascença: <strong>receber visão, tornar-se capaz de enxergar</strong> — Pausânias 4.12 [7].10, <span class=\"greek\">συνέβη τὸν Ὀφιονέα … τὸν ἐκ γενετῆς τυφλὸν ἀναβλέψαι</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>. <strong>b. Figuradamente, da visão interior:</strong> Herm. Wr. 7.3; 1a; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τίνι ἀνεβλέψατε;\" data-meanings=\"em que estado recebestes visão?\">ἐν τίνι ἀνεβλέψατε;</span>, <strong>em que estado recebestes visão?</strong>, 2 Cl 9.2; compare 1.6. — M-M.</p>\n</section></article><article id=\"entry-anablepsis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάβλεψις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anáblepsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Aristóteles e outros.) <strong>Recuperação da vista.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κηρῦξαι τυφλοῖς ἀνάβλεψιν\" data-meanings=\"proclamar aos cegos recuperação da vista\">κηρῦξαι τυφλοῖς ἀνάβλεψιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.18</a>; B 14.9; ambos com referência a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.61.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 61.1</a>.</p>\n</section></article><article id=\"entry-anaboao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβοάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaboáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεβόησα</span>. Ésquilo, Heródoto e outros; Antig. Car. 1; LXX; TestJob 19.3; Josefo, <em>Bell.</em> 5.120; <em>Ant.</em> 19.345; Justino, <em>A II</em> 12.7; Melito, <em>P.</em> 24, 166; raro em papiros: POxy 33 III, 7s.; PGM 36, 141. <strong>Gritar, clamar.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.8</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.38</a> v.l.; GJs 19.2. <span class=\"greek\">ἀ. φωνῇ μεγάλῃ</span>, <strong>clamar em alta voz</strong> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.28.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Rs 28.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 7.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/BEL.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Bel 41</a> Theod.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.51\" target=\"_blank\" rel=\"noopener noreferrer\">3Mc 5.51</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.42</a> v.l. <span class=\"greek\">ἀνεβόησε λέγων</span>, Josefo, <em>Ant.</em> 9.10; GPt 5.19. — DELG s.v. <span class=\"greek\">βοή</span>. M-M.</p>\n</section></article><article id=\"entry-anabole-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναβολή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anabolḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Heródoto e outros em vários sentidos; inscrições; papiros; LXX.) <strong>Adiamento, demora</strong> — Heródoto e outros; SIG 546, 22 [séc. III a.C.]; PAmh 3a II, 7; POxy 888, 5; PTebt 24, 22; Josefo, <em>Bell.</em> 7.69; <em>Ant.</em> 17.75. <span class=\"greek\">ἀ. ποιεῖσθαι</span>: Tucídides 2.42.4; Dionísio de Halicarnasso 11.33; Plutarco, <em>Camill.</em> 147 [35.3]; Josefo, <em>Ant.</em> 19.70.</p>\n<p class=\"entry-text\">Como termo técnico jurídico, <strong>adiamento, protelação</strong> — PAmh 34d, 5 [c. 157 a.C.] —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναβολὴν μηδεμίαν ποιησάμενος\" data-meanings=\"não tendo feito adiamento algum; não adiei a questão\">ἀναβολὴν μηδεμίαν ποιησάμενος</span>, <strong>não adiei a questão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.17</a>. Veja <span class=\"greek\">ἀναβάλλω</span>. — DELG s.v. <span class=\"greek\">βάλλω</span>. M-M.</p>\n</section></article><article id=\"entry-anagaion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάγαιον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anágaion⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek\">ἄνω</span> e <span class=\"greek\">γαῖα</span> [<span class=\"greek\">γῆ</span>], “algo elevado do chão”.) <strong>Um aposento no andar de cima</strong> — Varrão, <em>De Lingua Lat.</em> 5.162; PParis 21c, 19; PSI 709, 17, ambos do séc. VI d.C. —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.12</a>. Em ambos os lugares aparecem como variantes as formas dóricas <span class=\"greek\">ἀνώγαιον</span> e <span class=\"greek\">ἀνώγεον</span> — a última também em PParis citado acima —; compare Phryn. 297s. Lob.; Schwyzer I 632; II 537. Compare B-D-F §§25; 35, 2; 44, 1; W.-S. §5, 18; Mlt-H. 70; 76; 296. — M-M.</p>\n</section></article><article id=\"entry-anangello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγγέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anangéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναγγελῶ</span>; 1º aoristo <span class=\"greek\">ἀνήγγειλα</span>; infinitivo <span class=\"greek\">ἀναγγεῖλαι</span>; perfeito <span class=\"greek\">ἀνήγγελκα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Rs 3.13</a>. Passivo: futuro 3ª sg. <span class=\"greek\">ἀναγγελήσεται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 21.31</a>; 2º aoristo <span class=\"greek\">ἀνηγγέλην</span> — B-D-F §76, 1; Mlt-H. 226. Veja Anz 283s. sobre a história da palavra. Ésquilo, Tucídides e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Com a força plena de <span class=\"greek\">ἀνά</span>: <strong>levar de volta uma informação, relatar</strong>, de pessoas que retornam de um lugar — Xenofonte, <em>An.</em> 1.3.21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 9.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 11.15</a> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.14</a> v.l. <span class=\"greek\">τινί τι</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.11</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγέλλων ἡμῖν τὴν ὑμῶν ἐπιπόθησιν\" data-meanings=\"relatando-nos a vossa saudade\">ἀναγγέλλων ἡμῖν τὴν ὑμῶν ἐπιπόθησιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγέλλειν ὅσα ἐποίησεν ὁ θεός\" data-meanings=\"relatar o que Deus havia feito\">ἀ. ὅσα ἐποίησεν ὁ θεός</span>, <strong>relatar o que Deus havia feito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.27</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">15.4</a>. <span class=\"greek\">μὴ ἀναγγείλῃς ὅσα εἶδες</span>, GJs 20.4; <span class=\"greek\">ταῦτα</span>, 23.2, duas vezes; <span class=\"greek\">ἃ εἶδεν</span>, 24.2. Com <span class=\"greek\">ὅτι</span> seguinte: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.51s.</a> v.l.; GJs 24.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> De modo geral, <strong>fornecer informação, revelar, anunciar, proclamar, ensinar</strong> — equivalente ao ático <span class=\"greek\">ἀπαγγέλλω</span>, uso comum em inscrições e papiros, mas já presente em Ésquilo, <em>Prom.</em> 661, Xenofonte e outros; sobre a LXX, veja Anz 283s. <span class=\"greek\">αἴνεσιν</span>, <strong>o louvor de Deus</strong>, 1 Cl 18.15 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.17</a> —; <span class=\"greek\">ποίησιν χειρῶν</span>, <strong>a obra das mãos de Deus</strong>, 1 Cl 27.7 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 18.2</a>. <span class=\"greek\">τινί τι</span> — En 13.10; Josefo, <em>Bell.</em> 1.663; <em>Ant.</em> 5.114 —: <span class=\"greek\">ἀ. ταῦτα τοῖς ἐκλεκτοῖς</span>, Hv 2, 1, 3; compare 3, 3, 1; <span class=\"greek\">ἀ. τοῖς λοιποῖς τὰ γενόμενα</span>, MPol 15.1.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἐξομολογεῖσθαι</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγέλλειν τὰς πράξεις αὐτῶν\" data-meanings=\"tornar conhecidos os seus feitos\">ἀ. τὰς πράξεις αὐτῶν</span>, <strong>tornar conhecidos os seus feitos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.18</a>. De relatório a autoridades: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.11</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.15</a> — v.l. <span class=\"greek\">ἀπήγγειλεν</span>; veja Anz 283.</p>\n<p class=\"entry-text\">Da proclamação do que há de vir no futuro — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.41.22\" target=\"_blank\" rel=\"noopener noreferrer\">Is 41.22s.</a>; Taciano 13.3, <span class=\"greek\">πνεῦμα … διὰ προαγορεύσεων … τὸ κεκρυμμένον ἀνήγγειλε</span> —, por meio do Espírito: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἐρχόμενα ἀναγγελεῖ ὑμῖν\" data-meanings=\"ele vos anunciará as coisas que hão de vir\">τὰ ἐρχόμενα ἀ. ὑμῖν</span>, <strong>ele vos anunciará as coisas que hão de vir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.13</a>; compare vv. 14s. e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">4.25</a>. P. Joüon, <em>RSR</em> 28 (1938), 234s., entende aqui <span class=\"greek\">ἀναγγέλλω</span> como <strong>relatar o que se ouviu</strong>. De Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.25</a> v.l.</p>\n<p class=\"entry-text\">Da fala didática, <strong>pregar, ensinar</strong>: com <span class=\"greek\">διδάσκειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.20</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγεῖλαι πᾶσαν τὴν βουλὴν τοῦ θεοῦ\" data-meanings=\"anunciar todo o desígnio de Deus\">ἀ. πᾶσαν τὴν βουλὴν τοῦ θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">v. 27</a> — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 24.8</a>, <span class=\"greek\">τὸν νόμον</span>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἃ νῦν ἀνηγγέλη ὑμῖν\" data-meanings=\"as coisas que agora vos foram proclamadas\">ἃ νῦν ἀνηγγέλη ὑμῖν</span>, <strong>as coisas que agora vos foram proclamadas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.5</a>. <span class=\"greek\">ἀνηγγείλαμεν ἐναντίον αὐτοῦ</span>, <strong>proclamamos diante dele</strong>, 1 Cl 16.3 — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.2\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.2</a> —; compare GEb 121, 29. <span class=\"greek\">περί τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.21</a> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.52.15\" target=\"_blank\" rel=\"noopener noreferrer\">Is 52.15</a> —; 2 Cl 17.5. — M-M. TW.</p>\n</section></article><article id=\"entry-anagennao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγεννάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anagennáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεγέννησα</span>; passivo <span class=\"greek\">ἀνεγεννήθην</span> — Justino, Taciano —; particípio perfeito passivo <span class=\"greek\">ἀναγεγεννημένος</span> — Filodemo, <em>Ira</em> p. 18 W.; Sir Prol. ln. 28 v.l. <strong>Gerar de novo, fazer nascer de novo</strong>, figuradamente, do renascimento espiritual dos cristãos.</p>\n<p class=\"entry-text\">De Deus: <span class=\"greek\">ὁ ἀναγεννήσας ἡμᾶς εἰς ἐλπίδα ζῶσαν</span>, <strong>aquele que nos deu um novo nascimento para uma esperança viva</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.3</a>. <span class=\"greek\">ἀναγεγεννημένοι οὐκ ἐκ σπορᾶς φθαρτῆς</span>, <strong>nascidos de novo, não de semente perecível</strong>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>. Em Herm. Wr. 13, 1 Sc., <span class=\"greek\">ἀγνοῶ, ὦ τρισμέγιστε, ἐξ οἵας μήτρας ἄνθρωπος ἀναγεννηθείη ἄν, σπορᾶς δὲ ποίας</span>; a leitura <span class=\"greek\">ἀναγ.</span> não é certa. Salústio 4 p. 8, 24 = FPhGr III, 33, col. 2, 6 emprega a palavra ao descrever mistérios: <span class=\"greek\">γάλακτος τροφή, ὥσπερ ἀναγεννωμένων</span>.</p>\n<p class=\"entry-text\">Compare RPerdelwitz, <em>D. Mysterienreligion u. d. Problem des 1 Pt</em> 1911, 37ss.; HWindisch, <em>Hdb.</em>, <em>Exc.</em> sobre 1Pe 2.2; e o verbete <span class=\"greek\">παλιγγενεσία</span>. — DELG s.v. <span class=\"greek\">γίγνομαι</span> 222. M-M. TW. Sv.</p>\n</section></article>"};
